"""Build the complete, dependency-light static Pimento website.
Run with Python 3. No network requests; audited content is stored locally.
"""
from pathlib import Path
import json,re,html,unicodedata

ROOT=Path(__file__).resolve().parent
OUT=ROOT/'dist'
E=html.escape
recipes=json.loads((ROOT/'content/recipes.json').read_text(encoding='utf-8'))
source=json.loads((ROOT/'audit/content.json').read_text(encoding='utf-8'))
pages={p['id']:p for p in source}
template=(ROOT/'templates/home.html').read_text(encoding='utf-8')
header=re.search(r'<a class="skip".*?</header>',template).group()
header=header.replace('</a><nav class="desktop-nav"', '<span class="brand-tagline">YOU’LL LOVE THE KICK!</span></a><nav class="desktop-nav"')
header=header.replace('>Bestel Pimento <span', ' aria-label="Bestel Pimento in de externe webshop"><span class="shop-full">Bestel Pimento</span><span class="shop-short">Bestel</span> <span')
header=header.replace('>Bestel Pimento <span', ' aria-label="Bestel Pimento in de externe webshop"><span class="shop-full">Bestel Pimento</span><span class="shop-short">Bestel</span> <span')
head=re.search(r'<head>(.*?)</head>',template).group(1)
SHOP='https://shop.real-est-dranken.nl/32-pimento'
ARROW='<span aria-hidden="true">↗</span>'
categories=['Alcoholvrij','Gin','Rum','Wodka','Tequila','Overige cocktails','Shooters','Gerechten']
footer='''<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div><a class="footer-brand" href="/">PIMENTO.</a><p>Gember. Spuitwater. Chilipeper.<br>Een klein flesje met een eigen karakter.</p><span class="footer-tag">YOU’LL LOVE THE KICK!</span></div><div><h3>Ontdek</h3><a href="/pimento/">De smaak van Pimento</a><a href="/recepten/">Alle recepten</a><a href="/waar-te-koop/">Waar te koop</a><a href="/over-ons/">Over Pimento Nederland</a><a href="/promotie-agenda/">Proeven & evenementen</a></div><div><h3>Contact</h3><a href="mailto:info@real-est-dranken.nl">info@real-est-dranken.nl</a><a href="tel:+31611916408">06 1191 6408</a><a href="/contact/">Voor horeca & professionals</a><a href="https://www.facebook.com/pimentodrink.nl/" target="_blank" rel="noopener">Facebook ↗</a><a href="https://www.linkedin.com/in/pimento-drink-nederland-763520a8/" target="_blank" rel="noopener">LinkedIn ↗</a></div></div><div class="footer-bottom"><span>© Pimento Nederland · Uniqdrinks</span><div class="footer-legal"><a href="/algemene-voorwaarden/">Voorwaarden</a><a href="/disclaimer/">Disclaimer</a><a href="/sitemap/">Sitemap</a></div><span>Geniet bewust. Alcoholhoudende recepten: 18+.</span></div></div></footer>'''
def write(path,title,description,body,active='',extra=''):
    for cls in ['section-heading','moment-copy','flavour-list']:
        body=body.replace(f'class="{cls}"',f'class="{cls} reveal"')
    for cls in ['section-heading','moment-copy','flavour-list']:
        body=body.replace(f'class="{cls}"',f'class="{cls} reveal"')
    h=re.sub(r'<title>.*?</title>',f'<title>{E(title)}</title>',head)
    h=re.sub(r'<meta name="description" content="[^"]*">',f'<meta name="description" content="{E(description,quote=True)}">',h)
    h+=f'<meta property="og:title" content="{E(title,quote=True)}"><meta property="og:description" content="{E(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:locale" content="nl_NL"><meta name="theme-color" content="#f0f3ed">'+extra
    h+='<link rel="stylesheet" href="/pages.css"><link rel="stylesheet" href="/accessibility.css"><link rel="stylesheet" href="/brand.css">'
    nav=header.replace(f'href="{active}"',f'href="{active}" aria-current="page"') if active else header
    file=OUT/path.strip('/')/'index.html' if path else OUT/'index.html'
    file.parent.mkdir(parents=True,exist_ok=True)
    file.write_text(f'<!doctype html><html lang="nl"><head>{h}</head><body>{nav}<main id="main">{body}</main>{footer}<script src="/app.js" defer></script></body></html>',encoding='utf-8')
def button(text,url,cls=''):
    ext=' target="_blank" rel="noopener"' if url.startswith('https:') else ''
    return f'<a class="button {cls}" href="{url}"{ext}>{text}{ARROW}</a>'
def lead(kicker,title,text):
    return f'<section class="page-lead"><div class="wrap"><span class="eyebrow">{kicker}</span><h1>{title}</h1><p>{text}</p></div></section>'
def card(r,index=0,featured=False):
    cat=r['categories'][0]
    theme={'Alcoholvrij':'gold','Gin':'blue','Rum':'rust','Wodka':'green','Tequila':'gold','Overige cocktails':'rust','Shooters':'green','Gerechten':'gold'}[cat]
    artwork=''
    if featured:
        if r['slug']=='italian-mule':artwork='<img src="/assets/italian-mule.webp" width="960" height="750" loading="lazy" alt="De originele Italian Mule met limoen en munt">'
        else:artwork='<img src="/assets/bottle.webp" width="750" height="1700" loading="lazy" alt="Pimento Spicy Ginger" class="card-bottle">'
    art=f'<div class="card-art {theme}"><span class="art-label">{E(cat)}</span>{artwork}<span class="art-number">{index+1:02d}</span></div>' if featured else ''
    desc={'Alcoholvrij':'Fris, fruitig & met een kick','Gin':'Botanisch & verfrissend','Rum':'Rond, kruidig & vol karakter'}.get(cat,'Ontdek de mix met Pimento')
    search=E(' '.join([r['name']]+r['categories']+r.get('ingredients',r['lines'])),quote=True)
    return f'<article class="recipe-card {"featured" if featured else "compact"}" data-categories="{E("|".join(r["categories"]))}" data-search="{search}"><a href="/recepten/{r["slug"]}/">{art}<div class="card-copy"><span class="recipe-category">{E(cat)} {"· 18+" if cat not in ["Alcoholvrij","Gerechten"] else ""}</span><h3>{E(r["name"])}</h3><p>{desc if featured else "Bekijk het recept"}</p><span class="card-arrow" aria-hidden="true">↗</span></div></a></article>'
