# Preserve original legal text without silently rewriting its terms.
for pid,path in [(16,'algemene-voorwaarden'),(18,'disclaimer')]:
    raw=pages[pid]['html']
    raw=raw.replace('info@pimentodrink.nl','info@real-est-dranken.nl')
    raw=re.sub(r'\s(?:style|class|id)="[^"]*"','',raw)
    raw=raw.replace('<div>','<div class="legal-copy">',1)
    write(path,pages[pid]['title']+' — Pimento Nederland',pages[pid]['title']+' van Pimento Nederland.',lead('Pimento Nederland',pages[pid]['title'],'')+'<section class="section"><div class="wrap narrow">'+raw+'</div></section>')

